'use strict';

/** An error the user can fix: bad input, an unknown id, or an unreadable data file. */
class TodoError extends Error {
  constructor(message, options) {
    super(message, options);
    this.name = 'TodoError';
  }
}

function emptyState() {
  return { nextId: 1, todos: [] };
}

/**
 * Parses a command-line id. Only plain decimal digits are accepted, so "1.5",
 * "1e3", "-1" and " 1" are rejected rather than coerced by Number().
 */
function parseId(raw) {
  if (typeof raw !== 'string' || !/^\d+$/.test(raw)) {
    throw new TodoError(`Invalid id "${raw}". Expected a positive integer.`);
  }
  const id = Number(raw);
  if (id < 1 || !Number.isSafeInteger(id)) {
    throw new TodoError(`Invalid id "${raw}". Expected a positive integer.`);
  }
  return id;
}

/**
 * Returns a new state with the todo appended; the input state is not modified.
 * Whitespace runs (including newlines) collapse to one space so each todo
 * stays on a single line in `list` output.
 */
function addTodo(state, text, now = new Date()) {
  const normalized = typeof text === 'string' ? text.replace(/\s+/g, ' ').trim() : '';
  if (normalized === '') {
    throw new TodoError('Todo text cannot be empty.');
  }
  const todo = {
    id: state.nextId,
    text: normalized,
    completed: false,
    createdAt: now.toISOString(),
  };
  return {
    state: { ...state, nextId: state.nextId + 1, todos: [...state.todos, todo] },
    todo,
  };
}

function findIndex(state, id) {
  const index = state.todos.findIndex((todo) => todo.id === id);
  if (index === -1) {
    throw new TodoError(`Todo #${id} not found.`);
  }
  return index;
}

/**
 * Marks a todo as done. Completing an already-done todo is not an error;
 * `changed` is false in that case and the original state is returned.
 */
function completeTodo(state, id) {
  const index = findIndex(state, id);
  const existing = state.todos[index];
  if (existing.completed) {
    return { state, todo: existing, changed: false };
  }
  const todo = { ...existing, completed: true };
  const todos = state.todos.map((item, i) => (i === index ? todo : item));
  return { state: { ...state, todos }, todo, changed: true };
}

/** Removes a todo. `nextId` is left alone so a deleted id is never handed out again. */
function deleteTodo(state, id) {
  const index = findIndex(state, id);
  return {
    state: { ...state, todos: state.todos.filter((_, i) => i !== index) },
    todo: state.todos[index],
  };
}

function formatList(todos) {
  if (todos.length === 0) {
    return 'No todos yet.';
  }
  return todos.map((todo) => `${todo.id}. [${todo.completed ? 'x' : ' '}] ${todo.text}`).join('\n');
}

module.exports = {
  TodoError,
  emptyState,
  parseId,
  addTodo,
  completeTodo,
  deleteTodo,
  formatList,
};
'use strict';

// End-to-end tests: each case spawns `node index.js` in a fresh temp directory,
// which covers argument parsing, the store and the logic together.

const { describe, it, beforeEach, afterEach } = require('node:test');
const assert = require('node:assert/strict');
const { spawnSync } = require('node:child_process');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

const INDEX = path.join(__dirname, '..', 'index.js');

let dir;
let file;

beforeEach(() => {
  dir = fs.mkdtempSync(path.join(os.tmpdir(), 'todo-cli-'));
  file = path.join(dir, 'todos.json');
});

afterEach(() => {
  fs.rmSync(dir, { recursive: true, force: true });
});

function cli(...args) {
  const result = spawnSync(process.execPath, [INDEX, ...args], { cwd: dir, encoding: 'utf8', timeout: 10_000 });
  if (result.error) throw result.error;
  return { code: result.status, stdout: result.stdout, stderr: result.stderr };
}

function readData() {
  return JSON.parse(fs.readFileSync(file, 'utf8'));
}

function assertFails(result, message) {
  assert.equal(result.code, 1, `expected exit code 1, got ${result.code}: ${result.stdout}`);
  assert.equal(result.stdout, '');
  assert.match(result.stderr, message);
}

describe('add', () => {
  it('saves a pending todo to todos.json in the current directory', () => {
    const result = cli('add', 'Buy groceries');
    assert.equal(result.code, 0);
    assert.equal(result.stdout, 'Added todo #1: Buy groceries\n');

    const data = readData();
    assert.equal(data.nextId, 2);
    assert.equal(data.todos.length, 1);
    const [saved] = data.todos;
    assert.equal(saved.id, 1);
    assert.equal(saved.text, 'Buy groceries');
    assert.equal(saved.completed, false);
    assert.equal(new Date(saved.createdAt).toISOString(), saved.createdAt);
  });

  it('assigns auto-incrementing ids', () => {
    cli('add', 'first');
    cli('add', 'second');
    assert.equal(cli('add', 'third').stdout, 'Added todo #3: third\n');
    assert.deepEqual(readData().todos.map((t) => t.id), [1, 2, 3]);
  });

  it('joins unquoted words into one todo', () => {
    assert.equal(cli('add', 'Walk', 'the', 'dog').stdout, 'Added todo #1: Walk the dog\n');
  });

  it('stores unicode text unchanged', () => {
    cli('add', 'Café ☕ 買い物 👩‍💻');
    assert.equal(readData().todos[0].text, 'Café ☕ 買い物 👩‍💻');
    assert.equal(cli('list').stdout, '1. [ ] Café ☕ 買い物 👩‍💻\n');
  });

  it('fails without text and does not create the file', () => {
    assertFails(cli('add'), /Missing todo text/);
    assert.equal(fs.existsSync(file), false);
  });

  it('fails on whitespace-only text', () => {
    assertFails(cli('add', '   '), /Todo text cannot be empty/);
    assert.equal(fs.existsSync(file), false);
  });
});

describe('list', () => {
  it('reports an empty list when no file exists, without creating one', () => {
    const result = cli('list');
    assert.equal(result.code, 0);
    assert.equal(result.stdout, 'No todos yet.\n');
    assert.equal(fs.existsSync(file), false);
  });

  it('reports an empty list after every todo is deleted', () => {
    cli('add', 'only');
    cli('delete', '1');
    assert.equal(cli('list').stdout, 'No todos yet.\n');
  });

  it('shows id, status indicator and text for each todo', () => {
    cli('add', 'Buy groceries');
    cli('add', 'Walk the dog');
    cli('complete', '2');
    const result = cli('list');
    assert.equal(result.code, 0);
    assert.equal(result.stdout, '1. [ ] Buy groceries\n2. [x] Walk the dog\n');
  });

  it('rejects extra arguments', () => {
    assertFails(cli('list', 'all'), /takes no arguments/);
  });
});

describe('complete', () => {
  beforeEach(() => {
    cli('add', 'Buy groceries');
  });

  it('marks the todo as done', () => {
    const result = cli('complete', '1');
    assert.equal(result.code, 0);
    assert.equal(result.stdout, 'Completed todo #1: Buy groceries\n');
    assert.equal(readData().todos[0].completed, true);
  });

  it('succeeds without rewriting the file when the todo is already done', () => {
    cli('complete', '1');
    const before = fs.readFileSync(file, 'utf8');
    const result = cli('complete', '1');
    assert.equal(result.code, 0);
    assert.equal(result.stdout, 'Todo #1 is already completed.\n');
    assert.equal(fs.readFileSync(file, 'utf8'), before);
  });

  it('fails for an id that does not exist and leaves the file unchanged', () => {
    const before = fs.readFileSync(file, 'utf8');
    assertFails(cli('complete', '99'), /Todo #99 not found/);
    assert.equal(fs.readFileSync(file, 'utf8'), before);
  });

  it('fails for a non-numeric id', () => {
    assertFails(cli('complete', 'abc'), /Invalid id "abc"/);
  });

  it('fails for zero and negative ids', () => {
    assertFails(cli('complete', '0'), /Invalid id "0"/);
    assertFails(cli('complete', '-1'), /Invalid id "-1"/);
  });

  it('fails without an id', () => {
    assertFails(cli('complete'), /Missing todo id/);
  });

  it('fails with more than one id', () => {
    assertFails(cli('complete', '1', '2'), /Too many arguments/);
    assert.equal(readData().todos[0].completed, false);
  });
});

describe('delete', () => {
  beforeEach(() => {
    cli('add', 'Buy groceries');
    cli('add', 'Walk the dog');
  });

  it('removes the todo', () => {
    const result = cli('delete', '1');
    assert.equal(result.code, 0);
    assert.equal(result.stdout, 'Deleted todo #1: Buy groceries\n');
    assert.equal(cli('list').stdout, '2. [ ] Walk the dog\n');
  });

  it('never reuses the id of a deleted todo', () => {
    cli('delete', '2');
    assert.equal(cli('add', 'New').stdout, 'Added todo #3: New\n');
  });

  it('fails for an id that does not exist and leaves the file unchanged', () => {
    const before = fs.readFileSync(file, 'utf8');
    assertFails(cli('delete', '3'), /Todo #3 not found/);
    assert.equal(fs.readFileSync(file, 'utf8'), before);
  });

  it('fails when deleting the same id twice', () => {
    cli('delete', '1');
    assertFails(cli('delete', '1'), /Todo #1 not found/);
  });

  it('fails for an invalid id', () => {
    assertFails(cli('delete', '1.5'), /Invalid id "1.5"/);
  });

  it('fails without an id', () => {
    assertFails(cli('delete'), /Missing todo id/);
  });

  it('fails on an empty list', () => {
    fs.rmSync(file);
    assertFails(cli('delete', '1'), /Todo #1 not found/);
    assert.equal(fs.existsSync(file), false);
  });
});

describe('corrupted todos.json', () => {
  for (const args of [['list'], ['add', 'x'], ['complete', '1'], ['delete', '1']]) {
    it(`${args[0]} fails and leaves the file untouched`, () => {
      fs.writeFileSync(file, '{"nextId": 2, "todos": [');
      assertFails(cli(...args), /todos\.json is not valid JSON/);
      assert.equal(fs.readFileSync(file, 'utf8'), '{"nextId": 2, "todos": [');
    });
  }

  it('fails on valid JSON with the wrong shape', () => {
    fs.writeFileSync(file, '[]');
    assertFails(cli('list'), /todos\.json has invalid data/);
  });
});

describe('usage', () => {
  it('prints usage and fails when no command is given', () => {
    const result = cli();
    assertFails(result, /No command given/);
    assert.match(result.stderr, /Usage:/);
  });

  it('prints usage and fails on an unknown command', () => {
    const result = cli('remove', '1');
    assertFails(result, /Unknown command "remove"/);
    assert.match(result.stderr, /Usage:/);
  });

  for (const flag of ['help', '--help', '-h']) {
    it(`prints usage to stdout for ${flag}`, () => {
      const result = cli(flag);
      assert.equal(result.code, 0);
      assert.match(result.stdout, /^Usage:/);
      assert.equal(result.stderr, '');
    });
  }
});

describe('full workflow', () => {
  it('adds, completes, deletes and lists todos', () => {
    assert.equal(cli('add', 'Buy groceries').code, 0);
    assert.equal(cli('add', 'Walk the dog').code, 0);
    assert.equal(cli('add', 'Pay rent').code, 0);
    assert.equal(cli('complete', '1').code, 0);
    assert.equal(cli('delete', '2').code, 0);
    assert.equal(cli('list').stdout, '1. [x] Buy groceries\n3. [ ] Pay rent\n');
  });
});
