describe('list --pending', () => {
  it('shows only todos that are not completed, in the list format', () => {
    cli('add', 'Buy groceries');
    cli('add', 'Walk the dog');
    cli('add', 'Pay rent');
    cli('complete', '2');
    const result = cli('list', '--pending');
    assert.equal(result.code, 0);
    assert.equal(result.stdout, '1. [ ] Buy groceries\\n3. [ ] Pay rent\\n');
  });

  it('leaves plain list showing every todo', () => {
    cli('add', 'Buy groceries');
    cli('add', 'Walk the dog');
    cli('complete', '2');
    assert.equal(cli('list', '--pending').stdout, '1. [ ] Buy groceries\\n');
    assert.equal(cli('list').stdout, '1. [ ] Buy groceries\\n2. [x] Walk the dog\\n');
  });

  it('reports no pending todos when all are completed, without changing the file', () => {
