    assert.equal(cli('list', '--pending').stdout, 'No pending todos.\\n');
    assert.equal(fs.existsSync(file), false);
  });
});

describe('edit', () => {
  beforeEach(() => {
    cli('add', 'Buy groceries');
    cli('add', 'Walk the dog');
    cli('complete', '2');
  });

  it('replaces the text and keeps id, completed status and createdAt', () => {
    const before = readData();
    const result = cli('edit', '1', 'Buy milk');
    assert.equal(result.code, 0);
    assert.equal(result.stdout, 'Edited todo #1: Buy milk\\n');

    const after = readData();
    assert.equal(after.nextId, before.nextId);
    assert.deepEqual(after.todos[0], { ...before.todos[0], text: 'Buy milk' });
    assert.deepEqual(after.todos[1], before.todos[1]);
  });

  it('keeps a completed todo completed', () => {
    cli('edit', '2', 'Walk the cat');
    assert.equal(cli('list').stdout, '1. [ ] Buy groceries\\n2. [x] Walk the cat\\n');
    assert.equal(cli('list', '--pending').stdout, '1. [ ] Buy groceries\\n');
  });

  it('joins unquoted words and normalizes whitespace like add', () => {
    assert.equal(cli('edit', '1', 'Buy', 'oat', 'milk').stdout, 'Edited todo #1: Buy oat milk\\n');
    assert.equal(cli('edit', '1', '  Buy \\n  eggs ').stdout, 'Edited todo #1: Buy eggs\\n');
  });

  it('fails for an id that does not exist and leaves the file unchanged', () => {
    const before = fs.readFileSync(file, 'utf8');
