    assert.equal(fs.readFileSync(file, 'utf8'), before);
  });

  it('fails without an id', () => {
    const before = fs.readFileSync(file, 'utf8');
    assertFails(cli('edit'), /Missing todo id/);
    assert.equal(fs.readFileSync(file, 'utf8'), before);
  });

  it('fails without text and leaves the file unchanged', () => {
    const before = fs.readFileSync(file, 'utf8');
    assertFails(cli('edit', '1'), /Missing todo text/);
    assert.equal(fs.readFileSync(file, 'utf8'), before);
  });

